$ErrorActionPreference='Stop'
$projectRoot=Split-Path -Parent $PSScriptRoot
$path=Join-Path $projectRoot 'src\screens\IslamicHistoryScreen.tsx'
$source=[IO.File]::ReadAllText($path)
$source=$source.Replace("import {useState} from 'react';","import {useEffect,useRef,useState} from 'react';")
$source=$source.Replace("import {Modal,Pressable,ScrollView,StyleSheet,Text,View} from 'react-native';","import {Animated,Easing,Modal,Pressable,ScrollView,StyleSheet,Text,View} from 'react-native';")
$component=@'

const ERA_COLORS=['#087A4D','#B98B23','#2D7D73','#755C99','#A85F3A','#39749A'];

function EraCard({era,index,onOpen}:{era:Era;index:number;onOpen:()=>void}){
 const entrance=useRef(new Animated.Value(0)).current,press=useRef(new Animated.Value(1)).current,color=ERA_COLORS[index%ERA_COLORS.length];
 useEffect(()=>{Animated.timing(entrance,{toValue:1,duration:430,delay:index*55,easing:Easing.out(Easing.cubic),useNativeDriver:true}).start()},[entrance,index]);
 const animatePress=(toValue:number)=>Animated.spring(press,{toValue,speed:28,bounciness:4,useNativeDriver:true}).start();
 return <Animated.View style={[s.cardWrap,{opacity:entrance,transform:[{translateY:entrance.interpolate({inputRange:[0,1],outputRange:[22,0]})},{scale:press}]}]}><Pressable onPress={onOpen} onPressIn={()=>animatePress(.965)} onPressOut={()=>animatePress(1)} style={s.card}><View style={[s.accent,{backgroundColor:color}]}/><View style={s.motif}><View style={[s.motifRing,{borderColor:color+'24'}]}/><View style={[s.motifDot,{backgroundColor:color+'24'}]}/></View><View style={s.cardTop}><View style={[s.number,{backgroundColor:color+'18'}]}><Text style={[s.numberText,{color}]}>{String(index+1).padStart(2,'0')}</Text></View><View style={[s.openCircle,{backgroundColor:color}]}><Text style={s.openArrow}>{'\u203A'}</Text></View></View><Text style={[s.range,{color}]}>{era.range}</Text><Text style={s.cardTitle}>{era.title}</Text><Text style={s.cardSubtitle}>{era.subtitle}</Text><View style={s.cardFoot}><View style={[s.chapterPill,{backgroundColor:color+'12'}]}><View style={[s.dot,{backgroundColor:color}]}/><Text style={[s.chapterCount,{color}]}>{era.topics.length} chapters</Text></View></View></Pressable></Animated.View>;
}
'@
$source=$source.Replace("`nexport function IslamicHistoryScreen",$component+"`nexport function IslamicHistoryScreen")
$old='<View style={s.grid}>{ERAS.map((era,index)=><Pressable key={era.id} onPress={()=>setSelected(era)} style={({pressed})=>[s.card,pressed&&s.cardPressed]}><View style={s.cardTop}><View style={s.number}><Text style={s.numberText}>{String(index+1).padStart(2,''0'')}</Text></View><Text style={s.arrow}>{''\u203A''}</Text></View><Text style={s.range}>{era.range}</Text><Text style={s.cardTitle}>{era.title}</Text><Text style={s.cardSubtitle}>{era.subtitle}</Text><View style={s.cardFoot}><Text style={s.chapterCount}>{era.topics.length} chapters</Text><View style={s.dot}/></View></Pressable>)}</View>'
$new='<View style={s.grid}>{ERAS.map((era,index)=><EraCard key={era.id} era={era} index={index} onOpen={()=>setSelected(era)}/>)}</View>'
$source=$source.Replace($old,$new)
$oldStyles="grid:{flexDirection:'row',flexWrap:'wrap',justifyContent:'space-between',gap:10},card:{width:'48.5%',minHeight:190,padding:15,borderRadius:18,borderWidth:1,borderColor:'#DCE5DE',backgroundColor:'#fff',shadowColor:'#173D30',shadowOpacity:.07,shadowRadius:7,shadowOffset:{width:0,height:3},elevation:2},cardPressed:{opacity:.82,transform:[{scale:.985}]},cardTop:{flexDirection:'row',alignItems:'center'},number:{width:39,height:39,borderRadius:13,alignItems:'center',justifyContent:'center',backgroundColor:'#E6F4EA'},numberText:{fontSize:11,fontWeight:'900',color:GREEN},arrow:{marginLeft:'auto',fontSize:24,color:GREEN},range:{marginTop:15,fontSize:9,fontWeight:'900',letterSpacing:.6,color:GOLD},cardTitle:{marginTop:5,fontFamily:'serif',fontSize:16,lineHeight:20,fontWeight:'800',color:INK},cardSubtitle:{marginTop:5,fontSize:10,lineHeight:14,color:'#718078'},cardFoot:{marginTop:'auto',paddingTop:12,flexDirection:'row',alignItems:'center'},chapterCount:{fontSize:9,fontWeight:'800',color:GREEN},dot:{marginLeft:'auto',width:7,height:7,borderRadius:4,backgroundColor:'#D6B34B'},"
$newStyles="grid:{flexDirection:'row',flexWrap:'wrap',justifyContent:'space-between',gap:12},cardWrap:{width:'48.2%',borderRadius:20,shadowColor:'#173D30',shadowOpacity:.13,shadowRadius:10,shadowOffset:{width:0,height:5},elevation:4},card:{minHeight:205,padding:16,overflow:'hidden',borderRadius:20,borderWidth:1,borderColor:'#DCE5DE',backgroundColor:'#fff'},accent:{position:'absolute',left:0,top:0,bottom:0,width:4},motif:{position:'absolute',right:-22,top:48,width:86,height:86},motifRing:{position:'absolute',inset:0,borderWidth:12,borderRadius:43},motifDot:{position:'absolute',right:23,top:23,width:18,height:18,borderRadius:9},cardTop:{flexDirection:'row',alignItems:'center'},number:{width:42,height:42,borderRadius:14,alignItems:'center',justifyContent:'center'},numberText:{fontSize:11,fontWeight:'900'},openCircle:{marginLeft:'auto',width:30,height:30,borderRadius:15,alignItems:'center',justifyContent:'center'},openArrow:{marginTop:-2,fontSize:22,color:'#fff'},range:{marginTop:17,fontSize:9,fontWeight:'900',letterSpacing:.7},cardTitle:{maxWidth:'92%',marginTop:6,fontFamily:'serif',fontSize:17,lineHeight:21,fontWeight:'800',color:INK},cardSubtitle:{maxWidth:'90%',marginTop:6,fontSize:10,lineHeight:15,color:'#718078'},cardFoot:{marginTop:'auto',paddingTop:13,flexDirection:'row',alignItems:'center'},chapterPill:{flexDirection:'row',alignItems:'center',gap:6,paddingHorizontal:9,paddingVertical:6,borderRadius:999},chapterCount:{fontSize:9,fontWeight:'900'},dot:{width:6,height:6,borderRadius:3},"
$source=$source.Replace($oldStyles,$newStyles)
[IO.File]::WriteAllText($path,$source,[Text.UTF8Encoding]::new($false))
